import {clone,uid,block,ATTRS,layout,PROFILES} from './model.mjs';
export const nativeElements=[['name','Identificação','Aa'],['portrait','Retrato','▧'],['attributes','Atributos','◇'],['skills','Perícias','☷'],['resource','Recursos','▦'],['profile','Perfil','▰'],['ability','Habilidade','✦'],['rituals','Rituais','✧'],['equipment','Equipamento','▤'],['text','Texto','T'],['heading','Título','Aa'],['separator','Separador','—'],['shape','Retângulo','▭'],['circle','Círculo','○'],['frame','Moldura','▣'],['band','Faixa','▰'],['icon','Ícone','◆'],['image','Imagem','▧']];
export function createElement(doc,type,x=650,y=500){if(doc.blocks.length>=500)throw Error('Limite de 500 elementos por ficha.');const sizes={portrait:[500,800],image:[500,500],name:[800,100],attributes:[555,225],skills:[445,770],resource:[285,170],separator:[600,25],heading:[450,60],rituals:[625,490]};const size=sizes[type]||[500,220];const b=block(['circle','frame','band','icon'].includes(type)?'shape':type,nativeElements.find(e=>e[0]===type)?.[1]||'Elemento',x,y,...size,{body:type==='text'?'Escreva aqui.':'',resource:'pv'});if(['circle','frame','band','icon'].includes(type))b.shape=type;if(type==='heading')b.headingText='NOVO TÍTULO';if(type==='ability'){const a={id:uid(),title:'Nova habilidade',body:'Descreva esta habilidade.'};doc.abilities.push(a);b.ref=a.id;}doc.blocks.push(b);return b;}
function normalizeRefs(doc,blocks){return blocks.map(b=>{const c=clone(b);if(c.type==='ability'||c.binding?.startsWith('ability')){c.abilityIndex=doc.abilities.findIndex(a=>a.id===c.ref);delete c.ref;}if(c.type==='ritualPart'||c.binding?.startsWith('ritual')){c.ritualIndex=doc.rituals.findIndex(r=>r.id===c.ref);delete c.ref;}return c;});}
export function saveComponent(doc,ids,name){const blocks=doc.blocks.filter(b=>ids.includes(b.id));if(!blocks.length)throw Error('Selecione os elementos do componente.');return {id:uid(),kind:'component',name,blocks:normalizeRefs(doc,blocks),groups:clone((doc.groups||[]).filter(g=>blocks.some(b=>b.groupIds?.includes(g.id))))};}
function remap(item,doc,offset=0){const blocks=clone(item.blocks),ids=new Map(blocks.map(b=>[b.id,uid()])),groups=new Map((item.groups||[]).map(g=>[g.id,uid()]));for(const b of blocks){b.id=ids.get(b.id);b.x+=offset;b.y+=offset;b.preset=false;if(b.titleOf)b.titleOf=ids.get(b.titleOf);if(b.groupIds)b.groupIds=b.groupIds.map(g=>groups.get(g)).filter(Boolean);if(b.abilityIndex!==undefined)b.ref=doc.abilities[b.abilityIndex]?.id;if(b.ritualIndex!==undefined)b.ref=doc.rituals[b.ritualIndex]?.id;}return {blocks,groups:(item.groups||[]).map(g=>({...g,id:groups.get(g.id)}))};}
export function insertComponent(doc,item){if(doc.blocks.length+item.blocks.length>500)throw Error('Limite de 500 elementos por ficha.');const data=remap(item,doc,25);doc.blocks.push(...data.blocks);doc.groups=[...(doc.groups||[]),...data.groups];return data.blocks.map(b=>b.id);}
export function saveTemplate(doc,name,removePersonal=true){const item={...saveComponent(doc,doc.blocks.map(b=>b.id),name),kind:'template',theme:clone(doc.theme||{}),fonts:clone(doc.fonts||[]),background:doc.background,accent:doc.accent,showFrame:doc.showFrame,guides:clone(doc.guides||[])};if(removePersonal)for(const b of item.blocks){if(b.type==='text'){b.title='Texto';b.body='';delete b.richText;}if(b.type==='heading'&&!b.titleOf)b.headingText=b.headingText||b.title;}return item;}
export function applyTemplate(doc,item){const data=remap(item,doc);doc.blocks=data.blocks.filter(b=>b.type!=='ability'||b.ref);doc.groups=data.groups;if(doc.rituals.length&&!doc.blocks.some(b=>b.type==='rituals'||b.type==='ritualPart'||b.binding?.startsWith('ritual'))){const slot=data.blocks.find(b=>b.type==='ability');doc.blocks=doc.blocks.filter(b=>b.type!=='ability');doc.blocks.push(block('rituals','Rituais',slot?.x??1150,slot?.y??810,slot?.w??625,490));}for(let i=0;i<doc.abilities.length;i++){const a=doc.abilities[i];if(!doc.blocks.some(b=>b.ref===a.id)){const slot=data.blocks.find(b=>b.type==='ability');doc.blocks.push(block('ability',a.title,slot?.x??1150,(slot?.y??795)+i*250,slot?.w??625,slot?.h??225,{ref:a.id}));}}for(const k of ['theme','fonts','background','accent','showFrame','guides'])if(item[k]!==undefined)doc[k]=clone(item[k]);}
export function applyComposition(doc,name){layout(doc,'ordem');const presets=doc.blocks.filter(b=>b.preset);if(name==='central')return;if(name==='lateral'){for(const b of presets){if(b.type==='portrait')Object.assign(b,{x:100,y:300,w:500,h:850});if(b.type==='attributes')Object.assign(b,{x:650,y:300});if(b.type==='skills')Object.assign(b,{x:650,y:560});if(b.type==='equipment')Object.assign(b,{x:100,y:1180,w:500});}return;}
 const columns={uma:1,duas:2,tres:3,compacta:3,expandida:2}[name]||2,margin=120,gap=40,width=(1920-margin*2-gap*(columns-1))/columns;const flowing=presets.filter(b=>!['name','identity'].includes(b.type));const heights=Array(columns).fill(300);for(let i=0;i<flowing.length;i++){const b=flowing[i],col=i%columns;b.x=margin+col*(width+gap);b.y=heights[col];b.w=width;b.h=name==='compacta'?150:name==='expandida'?Math.min(420,b.h):Math.min(300,b.h);if(b.type==='portrait')b.h=name==='compacta'?280:350;if(b.type==='skills')b.h=name==='compacta'?400:550;heights[col]+=b.h+25;}for(let col=0;col<columns;col++){const items=flowing.filter((_,i)=>i%columns===col),end=Math.max(...items.map(b=>b.y+b.h)),factor=Math.min(1,1050/(end-300));if(factor<1)for(const b of items){b.y=300+(b.y-300)*factor;b.h=Math.max(25,b.h*factor);b.font=Math.max(12,b.font*factor);}}doc.layoutName={uma:'Uma coluna',duas:'Duas colunas',tres:'Três colunas',compacta:'Compacta',expandida:'Expandida'}[name]||name;}
export function splitComponent(doc,id){const b=doc.blocks.find(b=>b.id===id);if(!b||b.locked)return [];let specs=[];if(b.type==='attributeRow')specs=[['attrName',0,b.w-95],['attrValue',b.w-80,80]];if(b.type==='skillRow')specs=[['skillName',0,b.w-169],['skillValue',b.w-166,48],['skillAttribute',b.w-100,100]];if(b.type==='ability')specs=[['abilityTitle',0,b.w,0,42],['abilityBody',0,b.w,48,b.h-48]];if(b.type==='rituals'){const step=b.h/Math.max(1,doc.rituals.length);doc.rituals.forEach((r,i)=>specs.push(['ritualTitle',0,b.w,i*step,35,r.id],['ritualMeta',0,b.w,i*step+36,30,r.id],['ritualBody',0,b.w,i*step+70,Math.max(25,step-70),r.id]));}if(!specs.length)return [];const parts=specs.map(([binding,x,w,y=0,h=b.h,ref=b.ref])=>block('componentPart',b.title,b.x+x,b.y+y,Math.max(25,w),Math.max(25,h),{font:b.font,binding,ref,attr:b.attr,skillKey:b.skillKey,skillLabel:b.skillLabel,skillAttr:b.skillAttr,textStyle:clone(b.textStyle||{}),color:b.color}));doc.blocks.splice(doc.blocks.indexOf(b),1,...parts);return parts.map(b=>b.id);}
export function componentValue(b,d){const a=d.abilities.find(a=>a.id===b.ref),r=d.rituals.find(r=>r.id===b.ref);switch(b.binding){case 'attrName':return b.displayName||ATTRS[b.attr]||'';case 'attrValue':return 'd'+d.attrs[b.attr];case 'skillName':return b.displayName||b.skillLabel||b.skillKey;case 'skillValue':return 'd'+(d.skills[b.skillKey]||4);case 'skillAttribute':return 'd'+d.attrs[b.skillAttr];case 'abilityTitle':return a?.title||'';case 'abilityBody':return a?.body||'';case 'ritualTitle':return r?.title||'';case 'ritualMeta':return r?.meta||'';case 'ritualBody':return r?.body||'';default:return '';}}
